export const capf2015Questions: Capf2015ReviewQuestion[] = drafts.map(draft => {
  const answerLetter = capf2015AnswerKey[draft.questionNumber - 1];
  const answerIndex = "ABCD".indexOf(answerLetter);
  if (!answerLetter || answerIndex < 0 || draft.options.length !== 4) {
    throw new Error(`Invalid CAPF 2015 review entry ${draft.questionNumber}.`);
  }
  return {
    ...draft,
    id: capf2015Review.firstId + draft.questionNumber - 1,
    year: "2015",
    exam: "CAPF 2015",
    answerLetter,
    answer: draft.options[answerIndex],
  };
});

